WITH valid AS (SELECT id, customer_id, account_type, status, FLOOR(balance) AS balance_whole, DATEDIFF(CURRENT_DATE(), opened_date) AS days_since_opened_date, COALESCE(status, 'NONE') AS resolved_status FROM accounts WHERE opened_date > TO_DATE('2023-04-05')) SELECT CASE WHEN days_since_opened_date >= 71 THEN 'HIGH' ELSE 'LOW' END AS days_since_opened_date_tier, account_type, PERCENTILE_APPROX(balance_whole, 0.5) AS balance_whole_p50, COUNT(CASE WHEN status = 'FROZEN' THEN 1 END) AS frozen_count, SUM(days_since_opened_date) FILTER (WHERE account_type = 'CHECKING') AS checking_total_days_since_opened_date, SUM(CASE WHEN status = 'CLOSED' THEN days_since_opened_date ELSE 0 END) AS closed_days_since_opened_date, SIZE(COLLECT_SET(status)) AS num_status, GROUPING(CASE WHEN days_since_opened_date >= 71 THEN 'HIGH' ELSE 'LOW' END) AS gid FROM valid GROUP BY GROUPING SETS ((CASE WHEN days_since_opened_date >= 71 THEN 'HIGH' ELSE 'LOW' END, account_type), (CASE WHEN days_since_opened_date >= 71 THEN 'HIGH' ELSE 'LOW' END), ()) ORDER BY balance_whole_p50 DESC
